public class ThermostatDemo {
    public static void main(String[] args) {
        int[] readings = {64, 67, 72, 76, 80};

        System.out.println("Temp | Normal  | Eco");
        for (int temp : readings) {
            String normal = new Thermostat(temp, false).getStatus();
            String eco = new Thermostat(temp, true).getStatus();
            System.out.printf("%4d | %-7s | %s%n", temp, normal, eco);
        }
    }
}
